class Solution {
public:
    int uniquePathsWithObstacles(vector<vector<int>>& grid) {
        int row=grid.size();
        int col=grid[0].size();
        if(grid[0][0]==1)
            return 0;
        grid[0][0]=1;
        for(int i=1;i<row;i++)
        {
            if(grid[i][0]==0 and grid[i-1][0]==1)
                grid[i][0]=1;
            else
                grid[i][0]=0;
        }
        for(int j=1;j<col;j++)
        {
            if(grid[0][j]==0 and grid[0][j-1]==1)
                grid[0][j]=1;
            else
                grid[0][j]=0;
        }
        for(int i=1;i<row;i++)
        {
            for(int j=1;j<col;j++)
            {
                if(grid[i][j]==0)
                    grid[i][j]=grid[i-1][j]+grid[i][j-1];
                else
                    grid[i][j]=0;
            }
        }
        return grid[row-1][col-1];
    }
};

class Solution(object):
    def uniquePathsWithObstacles(self, obstacleGrid):
        """
        :type obstacleGrid: List[List[int]]
        :rtype: int
        """
        # classical DP
        m, n = len(obstacleGrid[0]), len(obstacleGrid)
        mat = [[0 for i in range(m)] for j in range(n)]

        # first row
        blocked = False
        for i in range(m):
            if obstacleGrid[0][i]==1:
                blocked = True
            mat[0][i]=1 if not blocked else 0

        # first column
        blocked = False
        for i in range(n):
            if obstacleGrid[i][0]==1:
                blocked = True
            mat[i][0]=1 if not blocked else 0

        for i in range(1, n):
            for j in range(1, m):
                if obstacleGrid[i][j]:
                    mat[i][j] = 0
                else:
                    mat[i][j] = mat[i-1][j]+mat[i][j-1]

        return mat[-1][-1]

